import{_ as a,o as r,c as e,a5 as o}from"./chunks/framework.Bt0SrEfo.js";const c=JSON.parse('{"title":"薪资谈判 & Offer 选择","description":"","frontmatter":{},"headers":[],"relativePath":"面试/薪资offer/14.薪资offer.md","filePath":"面试/薪资offer/14.薪资offer.md","lastUpdated":1791722830000}'),d={name:"面试/薪资offer/14.薪资offer.md"};function l(i,t,s,n,h,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="薪资谈判-offer-选择" tabindex="-1">薪资谈判 &amp; Offer 选择 <a class="header-anchor" href="#薪资谈判-offer-选择" aria-label="Permalink to &quot;薪资谈判 &amp; Offer 选择&quot;">​</a></h1><blockquote><p>拿到 offer 后，薪资谈判不是&quot;要多少&quot;，而是&quot;怎么要&quot;。<strong>谈薪 = 谈判</strong>，需要准备。</p></blockquote><hr><h2 id="一、薪酬结构认知" tabindex="-1">一、薪酬结构认知 <a class="header-anchor" href="#一、薪酬结构认知" aria-label="Permalink to &quot;一、薪酬结构认知&quot;">​</a></h2><h3 id="常见薪酬包" tabindex="-1">常见薪酬包 <a class="header-anchor" href="#常见薪酬包" aria-label="Permalink to &quot;常见薪酬包&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>占比</th><th>说明</th></tr></thead><tbody><tr><td><strong>基础月薪</strong></td><td>60-70%</td><td>12 薪 / 13 薪 / 14 薪</td></tr><tr><td><strong>绩效奖金</strong></td><td>10-20%</td><td>月度 / 季度 / 年度</td></tr><tr><td><strong>股票 / 期权</strong></td><td>10-30%</td><td>上市前溢价、上市后行权</td></tr><tr><td><strong>签字费</strong></td><td>一次性</td><td>大厂常用，5-20k 不等</td></tr><tr><td><strong>补贴</strong></td><td>5-10%</td><td>餐补 / 交通 / 通讯 / 房补</td></tr></tbody></table><h3 id="总包-total-package-的概念" tabindex="-1">总包（Total Package）的概念 <a class="header-anchor" href="#总包-total-package-的概念" aria-label="Permalink to &quot;总包（Total Package）的概念&quot;">​</a></h3><blockquote><p>谈薪时不仅看月薪，要看<strong>总包</strong>：基础月薪 × 月数 + 年终奖 + 股票折现 + 补贴。</p></blockquote><h3 id="期权折算参考" tabindex="-1">期权折算参考 <a class="header-anchor" href="#期权折算参考" aria-label="Permalink to &quot;期权折算参考&quot;">​</a></h3><ul><li>早期公司：保守折现 30-50%（风险溢价）</li><li>成长期公司：折现 50-70%</li><li>上市前：折现 70-90%</li><li>已上市：按当前股价 × 80%</li></ul><hr><h2 id="二、市场行情参考-2026-年" tabindex="-1">二、市场行情参考（2026 年） <a class="header-anchor" href="#二、市场行情参考-2026-年" aria-label="Permalink to &quot;二、市场行情参考（2026 年）&quot;">​</a></h2><blockquote><p>⚠️ 不同城市差异大、岗位级别差异大，仅作参考。</p></blockquote><h3 id="_7-年经验中位数-参考" tabindex="-1">7 年经验中位数（参考） <a class="header-anchor" href="#_7-年经验中位数-参考" aria-label="Permalink to &quot;7 年经验中位数（参考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>城市</th><th>高级 / 资深前端</th></tr></thead><tbody><tr><td>北京 / 上海 / 广州 / 杭州</td><td>25-45k × 13-16 薪</td></tr><tr><td>深圳</td><td>25-45k × 13-16 薪</td></tr><tr><td>二线（成都 / 武汉 / 南京）</td><td>18-30k × 13-15 薪</td></tr><tr><td>远程 / 出海</td><td>美元结算 5-9k USD/月</td></tr></tbody></table><h3 id="影响薪资的关键因素" tabindex="-1">影响薪资的关键因素 <a class="header-anchor" href="#影响薪资的关键因素" aria-label="Permalink to &quot;影响薪资的关键因素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>因素</th><th>加分</th><th>减分</th></tr></thead><tbody><tr><td><strong>业务匹配度</strong></td><td>B 端 SaaS 经验对口</td><td>完全跨业务</td></tr><tr><td><strong>技术深度</strong></td><td>源码级理解、能讲清原理</td><td>只用 API</td></tr><tr><td><strong>管理经验</strong></td><td>带过 3+ 人小组</td><td>主要为独立开发</td></tr><tr><td><strong>行业稀缺</strong></td><td>AI / 出海 / 安全方向</td><td>业务普通</td></tr><tr><td><strong>稳定性</strong></td><td>当前公司 3 年+</td><td>频繁跳槽</td></tr></tbody></table><hr><h2 id="三、谈薪步骤" tabindex="-1">三、谈薪步骤 <a class="header-anchor" href="#三、谈薪步骤" aria-label="Permalink to &quot;三、谈薪步骤&quot;">​</a></h2><h3 id="step-1-定锚-先报价" tabindex="-1">Step 1：定锚（先报价） <a class="header-anchor" href="#step-1-定锚-先报价" aria-label="Permalink to &quot;Step 1：定锚（先报价）&quot;">​</a></h3><blockquote><p>⚠️ <strong>自己先报价，别等 HR 问你期望</strong>。</p></blockquote><h4 id="报价策略" tabindex="-1">报价策略 <a class="header-anchor" href="#报价策略" aria-label="Permalink to &quot;报价策略&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报价 = 市场行情上沿 + 你的差异化 + 跳槽涨幅（30-50%）</span></span></code></pre></div><h4 id="_7-年经验人员参考话术" tabindex="-1">7 年经验人员参考话术 <a class="header-anchor" href="#_7-年经验人员参考话术" aria-label="Permalink to &quot;7 年经验人员参考话术&quot;">​</a></h4><blockquote><p>&quot;根据我的 7 年经验和项目匹配度，我期望 <strong>base 在 30-40k</strong>，总包 <strong>45-60 万</strong>。具体可以根据贵公司薪酬体系再议。&quot;</p></blockquote><h4 id="⚠️-报价注意事项" tabindex="-1">⚠️ 报价注意事项 <a class="header-anchor" href="#⚠️-报价注意事项" aria-label="Permalink to &quot;⚠️ 报价注意事项&quot;">​</a></h4><ul><li><strong>不要给精确数字</strong>（给区间，给上限）</li><li><strong>不要低于市场价 80%</strong>（HR 会压价）</li><li><strong>不要说&quot;按公司规定&quot;</strong>（暴露你没自信）</li></ul><h3 id="step-2-hr-反压-压价" tabindex="-1">Step 2：HR 反压（压价） <a class="header-anchor" href="#step-2-hr-反压-压价" aria-label="Permalink to &quot;Step 2：HR 反压（压价）&quot;">​</a></h3><h4 id="常见压价话术-应对" tabindex="-1">常见压价话术 + 应对 <a class="header-anchor" href="#常见压价话术-应对" aria-label="Permalink to &quot;常见压价话术 + 应对&quot;">​</a></h4><table tabindex="0"><thead><tr><th>HR 说</th><th>你回</th></tr></thead><tbody><tr><td>&quot;你的期望太高了&quot;</td><td>&quot;我做了调研，7 年 + 我这个项目经验，市场上 X-Y k 是合理区间。贵公司这个级别是 15k / 20k？&quot;</td></tr><tr><td>&quot;我们这边薪酬带宽比较窄&quot;</td><td>&quot;明白，那 base 这块幅度不大，<strong>年终奖 / 股票 / 签字费</strong>这边有调整空间吗？&quot;</td></tr><tr><td>&quot;我们需要综合评估&quot;</td><td>&quot;完全理解，那我等您这边的反馈。如果薪酬差距过大，我也希望您直说，我重新评估。&quot;</td></tr><tr><td>&quot;前公司薪资多少？&quot;</td><td>&quot;前公司 base XXk。这次主要看的是<strong>未来发展 + 整体总包</strong>，希望涨幅 30%+，具体数字可以议。&quot;</td></tr><tr><td>&quot;我们可以给你 P6 职级，base 23k&quot;</td><td>&quot;职级我接受。但 base 这边和我期望差距比较大，能不能<strong>额外签字费 / 提前 review</strong> 调整？&quot;</td></tr></tbody></table><h3 id="step-3-争取额外福利" tabindex="-1">Step 3：争取额外福利 <a class="header-anchor" href="#step-3-争取额外福利" aria-label="Permalink to &quot;Step 3：争取额外福利&quot;">​</a></h3><p>如果 base 压不动，争取以下：</p><ul><li><strong>签字费</strong>（5-20k，一次性）</li><li><strong>股票 / 期权</strong>（额外 0.0X%）</li><li><strong>提前 review</strong>（3-6 个月可调薪）</li><li><strong>远程办公</strong>（每周 1-2 天）</li><li><strong>培训预算</strong>（会议 / 课程）</li><li><strong>入职时间</strong>（多争取 1-2 周过渡）</li></ul><h3 id="step-4-落槌-白纸黑字" tabindex="-1">Step 4：落槌（白纸黑字） <a class="header-anchor" href="#step-4-落槌-白纸黑字" aria-label="Permalink to &quot;Step 4：落槌（白纸黑字）&quot;">​</a></h3><p>口头 offer 不算数，<strong>必须拿到书面 offer（邮件 / Offer Letter）</strong>，包含：</p><ul><li>[ ] Base 月薪</li><li>[ ] 月数（12 / 13 / 14）</li><li>[ ] 绩效奖金比例</li><li>[ ] 股票 / 期权数量 + 行权价</li><li>[ ] 签字费</li><li>[ ] 入职日期</li><li>[ ] 试用期时长 + 试用期薪资</li><li>[ ] 报销 / 补贴</li></ul><hr><h2 id="四、多个-offer-比较" tabindex="-1">四、多个 Offer 比较 <a class="header-anchor" href="#四、多个-offer-比较" aria-label="Permalink to &quot;四、多个 Offer 比较&quot;">​</a></h2><h3 id="决策矩阵" tabindex="-1">决策矩阵 <a class="header-anchor" href="#决策矩阵" aria-label="Permalink to &quot;决策矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>权重</th><th>Offer A</th><th>Offer B</th></tr></thead><tbody><tr><td><strong>Base</strong></td><td>25%</td><td>30k × 13</td><td>28k × 16</td></tr><tr><td><strong>总包</strong></td><td>25%</td><td>39 万</td><td>45 万</td></tr><tr><td><strong>业务</strong></td><td>20%</td><td>B 端 SaaS</td><td>C 端营销</td></tr><tr><td><strong>团队 / 成长</strong></td><td>15%</td><td>大团队</td><td>创业团队</td></tr><tr><td><strong>通勤</strong></td><td>5%</td><td>1 小时</td><td>步行 15 分</td></tr><tr><td><strong>稳定性</strong></td><td>10%</td><td>上市公司</td><td>B 轮</td></tr></tbody></table><h3 id="决策原则" tabindex="-1">决策原则 <a class="header-anchor" href="#决策原则" aria-label="Permalink to &quot;决策原则&quot;">​</a></h3><ul><li><strong>总包优先</strong>：base × 月数 + 期权折现 + 签字费</li><li><strong>业务优先</strong>：未来 3-5 年的简历加分项</li><li><strong>团队优先</strong>：直属 leader 比公司更重要</li><li><strong>通勤其次</strong>：远程优先（节省 2 小时/天）</li></ul><hr><h2 id="五、拒绝-offer" tabindex="-1">五、拒绝 Offer <a class="header-anchor" href="#五、拒绝-offer" aria-label="Permalink to &quot;五、拒绝 Offer&quot;">​</a></h2><h3 id="不要做的事" tabindex="-1">不要做的事 <a class="header-anchor" href="#不要做的事" aria-label="Permalink to &quot;不要做的事&quot;">​</a></h3><ul><li>❌ 拖着不回（HR 在等你推进流程）</li><li>❌ &quot;我再想想&quot;——直接说&quot;感谢，我决定不接&quot;</li><li>❌ 反向压价（HR 会觉得你不靠谱）</li><li>❌ 把一个 Offer 当杠杆（一旦暴露，HR 会撤销）</li></ul><h3 id="参考话术" tabindex="-1">参考话术 <a class="header-anchor" href="#参考话术" aria-label="Permalink to &quot;参考话术&quot;">​</a></h3><blockquote><p>&quot;非常感谢贵公司的 offer，团队氛围和项目都很吸引我。但综合考虑了<strong>业务方向 / 团队阶段 / 通勤成本</strong>之后，我决定不加入贵公司。如果将来有合作机会，非常期待。&quot;</p></blockquote><hr><h2 id="六、薪资倒挂-跳槽涨幅" tabindex="-1">六、薪资倒挂 &amp; 跳槽涨幅 <a class="header-anchor" href="#六、薪资倒挂-跳槽涨幅" aria-label="Permalink to &quot;六、薪资倒挂 &amp; 跳槽涨幅&quot;">​</a></h2><h3 id="跳槽涨幅公式" tabindex="-1">跳槽涨幅公式 <a class="header-anchor" href="#跳槽涨幅公式" aria-label="Permalink to &quot;跳槽涨幅公式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>合理涨幅 = 当前 base × (1.3 ~ 1.5)</span></span></code></pre></div><ul><li>横向跳槽：30-50%</li><li>升级（中级 → 高级）：40-60%</li><li>跨级 / 跨业务：50-80%</li><li>大厂 → 创业公司：50-100%（补期权）</li></ul><h3 id="反向倒挂风险" tabindex="-1">反向倒挂风险 <a class="header-anchor" href="#反向倒挂风险" aria-label="Permalink to &quot;反向倒挂风险&quot;">​</a></h3><ul><li>老员工涨薪慢，新人 base 高 → 公司 HRBP 通常会有专项调整</li><li>主动出击：<strong>年度 review 时拿着市场数据 + 业绩谈调薪</strong></li></ul><hr><h2 id="📌-准备清单-hr-面之前-1-天" tabindex="-1">📌 准备清单（HR 面之前 1 天） <a class="header-anchor" href="#📌-准备清单-hr-面之前-1-天" aria-label="Permalink to &quot;📌 准备清单（HR 面之前 1 天）&quot;">​</a></h2><ul><li>[ ] 调研目标岗位市场行情（Boss 直聘、看准网）</li><li>[ ] 报价区间想好（给上限 + 10%）</li><li>[ ] 准备 3 个额外福利选项（签字费 / 股票 / 远程）</li><li>[ ] 准备 2 个反问问题（团队 / 业务 / 培训）</li><li>[ ] 准备拒绝话术（如果 base 差距过大）</li></ul><h2 id="🔗-相关文档" tabindex="-1">🔗 相关文档 <a class="header-anchor" href="#🔗-相关文档" aria-label="Permalink to &quot;🔗 相关文档&quot;">​</a></h2><ul><li><a href="./../3-自我介绍">自我介绍</a></li><li><a href="./../工作经历/">工作经历问题准备</a></li><li><a href="./../面试技巧/15.线下面试技巧">面试技巧大全</a></li></ul>',60)])])}const q=a(d,[["render",l]]);export{c as __pageData,q as default};
